package com.campusnova.knowledge;
/** A safe, displayable piece of institution-owned knowledge. */
public class KnowledgeDocument { private final String source; private final String category; private final String content; private final boolean verified; private final boolean official; private final String sourceUrl; public KnowledgeDocument(String source,String category,String content,boolean verified){this(source,category,content,verified,false,null);} public KnowledgeDocument(String source,String category,String content,boolean verified,boolean official,String url){this.source=source;this.category=category;this.content=content;this.verified=verified;this.official=official;sourceUrl=url;} public String getSource(){return source;} public String getCategory(){return category;} public String getContent(){return content;} public boolean isVerified(){return verified;} public boolean isOfficial(){return official;} public String getSourceUrl(){return sourceUrl;} }
